# Content for the Train and Focus pillars and the quizzes. Plain data; build.py turns it into pages.

GAMES = [
 dict(id='reaction', slug='reaction-time', name='Reaction time test', short='Reaction time',
  blurb='Click when the pad turns green. Five trials, averaged in milliseconds.',
  measures='Simple visual reaction time: the gap between a signal appearing and your response. The number bundles four things together: how fast your eyes register the change, how fast your brain decides, how fast your finger moves, and the lag in your screen and input device.',
  science='<p>Reaction time is one of the oldest measurements in psychology; Francis Galton collected thousands of readings in his London laboratory in the 1880s. In controlled lab studies healthy young adults usually answer a visual signal in roughly 200 to 250 milliseconds. Browser tests run slower, because displays, wireless mice and touchscreens each add delay.</p><p>The number moves with your state. Fatigue, alcohol and divided attention slow it, and so does choice: Hick’s law says decision time rises with the logarithm of the number of options. That is why this test uses one signal and one response.</p>',
  improve=['Run one warm-up round before the round you count. First attempts are usually the slowest.','Use a wired mouse on a desktop monitor if you can. Hardware lag is often 30 to 80 ms.','Test at the same time of day when you compare runs. Alertness changes through the day.','Do not guess the timing. Early clicks are discarded, and guessing makes the average meaningless.'],
  table=[('Under 200 ms','Exceptional'),('200 to 249 ms','Fast'),('250 to 299 ms','Typical'),('300 to 399 ms','On the slow side'),('400 ms or more','Slow run, usually fatigue or distraction')],
  sources=['Hick, W. E. (1952). On the rate of gain of information. Quarterly Journal of Experimental Psychology.','Woods, D. L., Wyma, J. M., Yund, E. W., Herron, T. J., &amp; Reed, B. (2015). Factors influencing the latency of simple reaction time. Frontiers in Human Neuroscience.']),
 dict(id='number', slug='number-memory', name='Number memory test', short='Number memory',
  blurb='Remember a number that grows by one digit each round.',
  measures='Digit span: how many digits you can hold in short-term memory long enough to repeat them. It leans on the verbal part of working memory, the inner voice that rehearses a phone number while you look for a pen.',
  science='<p>George Miller’s 1956 paper put the typical span at “seven, plus or minus two” items. Later work by Nelson Cowan argued the true limit is closer to four chunks once rehearsal and grouping are prevented. Both can be right: a chunk can hold several digits, so 1-9-4-5 is four items to one person and a single year to another.</p><p>Chunking is also why span is trainable on this exact task. In a well-known study by Ericsson, Chase and Faloon, a student raised his digit span from about 7 to about 80 over many months by recoding digits as running times. His memory for letters did not improve at all.</p>',
  improve=['Group digits in threes or fours, the way phone numbers are written.','Say the groups in a rhythm under your breath. Rehearsal keeps the sound trace alive.','Attach meaning where you can: years, prices, ages, sports scores.','Look away from the screen the moment the number disappears and repeat it once before typing.'],
  table=[('12 or more digits','Exceptional'),('9 to 11 digits','Strong'),('6 to 8 digits','Typical'),('5 or fewer digits','Below the usual range')],
  sources=['Miller, G. A. (1956). The magical number seven, plus or minus two. Psychological Review.','Cowan, N. (2001). The magical number 4 in short-term memory. Behavioral and Brain Sciences.','Ericsson, K. A., Chase, W. G., &amp; Faloon, S. (1980). Acquisition of a memory skill. Science.']),
 dict(id='sequence', slug='sequence-memory', name='Sequence memory test', short='Sequence memory',
  blurb='Repeat a growing pattern of tiles. One slip ends the run.',
  measures='Visuospatial sequence memory: holding a series of locations, in order, for a few seconds. It uses the spatial side of working memory, the part you rely on to remember a route or the order of steps on a screen.',
  science='<p>This is a browser version of the Corsi block-tapping task, introduced by Philip Corsi in 1972 and still used in clinics and labs. An examiner taps a set of blocks in order and the person taps them back; the longest sequence repeated correctly is the span. Healthy adults usually manage about five or six blocks on the original task.</p><p>In Baddeley and Hitch’s model of working memory, tasks like this draw on a “visuospatial sketchpad” that is separate from the verbal loop used for digits. That is why your number-memory and sequence-memory results can differ a lot.</p>',
  improve=['Turn the sequence into a path or a shape: an L, a zigzag, a loop.','Name positions as you watch (top left, centre, bottom right) to recruit verbal memory as a backup.','Follow with your eyes, not your cursor. Moving the mouse during playback splits attention.','Keep a steady tapping rhythm. Rushing the last two tiles is the usual way runs end.'],
  table=[('13 or more steps','Exceptional'),('9 to 12 steps','Strong'),('5 to 8 steps','Typical'),('4 or fewer steps','Early exit')],
  sources=['Corsi, P. M. (1972). Human memory and the medial temporal region of the brain. Doctoral thesis, McGill University.','Baddeley, A. D., &amp; Hitch, G. (1974). Working memory. In The Psychology of Learning and Motivation.']),
 dict(id='visual', slug='visual-memory', name='Visual memory test', short='Visual memory',
  blurb='Tiles flash on a grid. Click the same tiles from memory.',
  measures='Visual pattern memory: how much of a briefly seen layout you can hold at once. Unlike the sequence test, order does not matter here; only the pattern does.',
  science='<p>Research on visual working memory, including a much-cited 1997 study by Luck and Vogel, suggests people hold only about three or four separate objects at a time. Yet most people can reproduce patterns of eight or more tiles. The difference is chunking: neighbouring tiles fuse into shapes, and a shape counts as one object.</p><p>Clinical pattern-span tests such as the Visual Patterns Test work the same way, with grids that grow until recall breaks down. Scores depend heavily on how regular the pattern happens to be, so expect your results to swing from run to run.</p>',
  improve=['Look for shapes, not tiles: a row of three, a diagonal, a square.','Fix your gaze on the centre of the grid and take in the whole pattern at once.','Click the shape you are surest of first, before it fades.','Use your three misses per round. A guess next to a known tile is better than a random one.'],
  table=[('13 or more tiles','Exceptional'),('10 to 12 tiles','Strong'),('6 to 9 tiles','Typical'),('5 or fewer tiles','Early exit')],
  sources=['Luck, S. J., &amp; Vogel, E. K. (1997). The capacity of visual working memory for features and conjunctions. Nature.','Della Sala, S., Gray, C., Baddeley, A., Allamano, N., &amp; Wilson, L. (1999). Pattern span: a tool for unwelding visuo-spatial memory. Neuropsychologia.']),
 dict(id='stroop', slug='stroop-test', name='Stroop test', short='Stroop test',
  blurb='Name the ink colour, ignore the word. Measures interference in milliseconds.',
  measures='Selective attention and inhibition: how well you can act on one feature of something (the ink colour) while suppressing an automatic response to another (reading the word). The score is your Stroop interference, the extra time clashing trials cost you compared with matching ones.',
  science='<p>John Ridley Stroop published the effect in 1935, and it has become one of the most replicated findings in psychology. Reading is so practised that it runs automatically; when the word says RED but the ink is blue, the wrong answer arrives first and has to be overridden. That override takes measurable time.</p><p>A 1991 review by Colin MacLeod covered half a century of studies using the task. Interference grows with fatigue and divided attention, which makes it a useful, if rough, check on how well you are focusing right now. It is not a diagnosis of anything.</p>',
  improve=['Answer accurately first. Below about 75% correct, the timing stops meaning much, so the test will not save the score.','Soften your gaze so the word blurs slightly; you need the colour, not the letters.','Keep one finger over each number key instead of hunting for buttons.','Compare runs taken in the same condition: morning with morning, rested with rested.'],
  table=[('Under 40 ms','Minimal interference'),('40 to 129 ms','Typical interference'),('130 ms or more','Strong interference')],
  sources=['Stroop, J. R. (1935). Studies of interference in serial verbal reactions. Journal of Experimental Psychology.','MacLeod, C. M. (1991). Half a century of research on the Stroop effect: an integrative review. Psychological Bulletin.']),
 dict(id='nback', slug='n-back', name='2-back test', short='2-back',
  blurb='Press Match when a letter repeats the one two steps back.',
  measures='Working-memory updating: keeping a short list in mind while you keep replacing its contents. Each new letter has to be compared with the one two steps earlier, stored, and then used as the comparison two letters later.',
  science='<p>Wayne Kirchner introduced the n-back task in 1958, and it became a standard tool in brain-imaging research on working memory. It jumped into public view in 2008 when Jaeggi and colleagues reported that training on a dual n-back raised scores on a test of fluid intelligence.</p><p>That claim has not held up cleanly. A careful replication attempt by Redick and colleagues in 2013 found no such gain, and a meta-analysis by Melby-Lervåg and Hulme concluded that working-memory training produces short-term improvements on the trained tasks without reliable transfer to general ability. So treat this as a demanding attention drill and an honest measure of how sharp you are today, not as an intelligence booster.</p>',
  improve=['Whisper each letter. A spoken chain of the last three letters is easier to update than a mental picture.','Do not chase a missed letter. Let it go and rebuild the chain from the next one.','Start with the 1-back practice round until the rhythm feels easy.','False alarms count against you, so only press when you are fairly sure.'],
  table=[('85 points or more','Exceptional'),('65 to 84 points','Strong'),('35 to 64 points','Typical'),('Under 35 points','Finding your feet')],
  sources=['Kirchner, W. K. (1958). Age differences in short-term retention of rapidly changing information. Journal of Experimental Psychology.','Jaeggi, S. M., Buschkuehl, M., Jonides, J., &amp; Perrig, W. J. (2008). Improving fluid intelligence with training on working memory. PNAS.','Redick, T. S., et al. (2013). No evidence of intelligence improvement after working memory training. Journal of Experimental Psychology: General.','Melby-Lervåg, M., &amp; Hulme, C. (2013). Is working memory training effective? A meta-analytic review. Developmental Psychology.']),
 dict(id='math', slug='mental-math', name='Mental math sprint', short='Mental math',
  blurb='Sixty seconds of sums. The next one appears the instant you are right.',
  measures='Arithmetic fluency: how quickly you can pull number facts from memory and carry small calculations in your head. The score is the number of correct answers in one minute, typing included.',
  science='<p>Research on mental arithmetic, reviewed by Mark Ashcraft in 1992, shows that adults solve simple sums mostly by retrieval, not calculation: 7 × 8 is looked up, not worked out. Larger problems take longer (the “problem-size effect”) because the facts are practised less often and because carrying uses working memory.</p><p>That makes this one of the most trainable tests on the site. A few short sessions a week rebuild retrieval speed quickly, and unlike most brain-training gains, faster arithmetic is useful in itself.</p>',
  improve=['Skip a sum the moment it stalls you. Ten seconds on one problem costs three easy ones.','For subtraction, count up from the smaller number instead of borrowing.','Split multiplication: 7 × 14 is 7 × 10 plus 7 × 4.','Keep your eyes on the sum, not the timer.'],
  table=[('30 or more correct','Exceptional'),('20 to 29 correct','Fast'),('10 to 19 correct','Typical'),('Under 10 correct','Warm-up pace')],
  sources=['Ashcraft, M. H. (1992). Cognitive arithmetic: a review of data and theory. Cognition.']),
 dict(id='verbal', slug='verbal-memory', name='Verbal memory test', short='Verbal memory',
  blurb='Seen it or new? Keep words apart as the list grows.',
  measures='Recognition memory for words: telling items you have met during the round from similar items you have not. As the list grows, the difficulty shifts from remembering to resisting false familiarity.',
  science='<p>This is a continuous recognition task, a design used by Shepard and Teghtsoonian in 1961 to study how memory behaves when new items keep arriving. Accuracy falls as more items intervene between the first and second showing of a word, and “new” words start to feel familiar simply because they resemble earlier ones.</p><p>How you process each word matters more than how hard you stare at it. Craik and Lockhart’s levels-of-processing work showed that thinking about a word’s meaning leaves a stronger trace than noticing its letters or sound.</p>',
  improve=['Give every new word a one-second mental picture. Meaning sticks better than spelling.','Link a new word to the previous one in a tiny scene: a dolphin wearing a helmet.','When unsure, ask whether you can recall your picture for the word. No picture usually means new.','Take your time. This test has no clock.'],
  table=[('60 or more words','Exceptional'),('35 to 59 words','Strong'),('15 to 34 words','Typical'),('Under 15 words','Early exit')],
  sources=['Shepard, R. N., &amp; Teghtsoonian, M. (1961). Retention of information under conditions approaching a steady state. Journal of Experimental Psychology.','Craik, F. I. M., &amp; Lockhart, R. S. (1972). Levels of processing: a framework for memory research. Journal of Verbal Learning and Verbal Behavior.']),
 dict(id='schulte', slug='schulte-table', name='Schulte table', short='Schulte table',
  blurb='Find the numbers 1 to 25 in order, as fast as you can.',
  measures='Visual search speed and sustained attention: how quickly you can find a known target among distractors, twenty-five times in a row, without losing your place.',
  science='<p>Schulte tables are named after the German psychiatrist Walter Schulte and have been used for decades in attention training and speed-reading courses. The task is a serial visual search: each number has to be found among 24 look-alikes, the kind of search Treisman and Gelade’s feature-integration theory describes as slow and attention-hungry.</p><p>An evidence note: practice clearly makes you faster at Schulte tables, but controlled evidence that this transfers to reading speed is thin. Use it as a two-minute attention warm-up before focused work, not as a reading cure.</p>',
  improve=['Rest your gaze on the centre tile and widen your attention instead of scanning line by line.','Hold the next two numbers in mind so you can spot the second while clicking the first.','Stay loose after a wrong click. One miss costs half a second; tensing up costs more.','Run three tables in a row. The third is usually your fastest.'],
  table=[('Under 25 seconds','Exceptional'),('25 to 34 seconds','Fast'),('35 to 49 seconds','Typical'),('50 seconds or more','Slow run')],
  sources=['Treisman, A. M., &amp; Gelade, G. (1980). A feature-integration theory of attention. Cognitive Psychology.']),
]

TOOLS = [
 dict(id='timer', slug='focus-timer', name='Focus timer', blurb='A Pomodoro timer with a task list and a daily count.',
  intro='Work in timed focus sessions with short breaks between them. Add the tasks you plan to work on, click one to make it active, and the timer counts sessions against it.',
  how=['Add the one task you will work on first.','Start a 25-minute focus session and work on that task only.','When the beeps sound, take the five-minute break away from the screen.','After four sessions, take the long break. Change any of the lengths under the timer.'],
  why='<p>The method is Francesco Cirillo’s Pomodoro Technique, which he developed as a student in the late 1980s using a tomato-shaped kitchen timer. The mechanics are simple, and that is the point: a short, fixed interval lowers the cost of starting, and a visible countdown makes drifting to email feel like breaking a promise.</p><p>The breaks matter as much as the sessions. In a 2011 study, Ariga and Lleras found that people who took brief breaks during a 50-minute attention task held their performance, while those who worked straight through declined. If 25 minutes feels short for deep technical work, set 50 and 10 instead; the structure matters more than the number.</p>',
  sources=['Cirillo, F. (2006). The Pomodoro Technique.','Ariga, A., &amp; Lleras, A. (2011). Brief and rare mental “breaks” keep you focused. Cognition.']),
 dict(id='breathe', slug='breathing-pacer', name='Breathing pacer', blurb='Guided slow breathing in four patterns, from one to ten minutes.',
  intro='Follow the circle: breathe in as it grows, out as it shrinks, and hold when it pauses. Pick a pattern, pick a length, and breathe through your nose if you can.',
  how=['Sit upright with both feet on the floor.','Choose a pattern. Box breathing is the easiest to follow; long exhale is the most calming for most people.','Breathe low into your belly, quietly, without forcing a big breath.','Stop if you feel dizzy or uncomfortable, and breathe normally.'],
  why='<p>Slowing your breathing to around six breaths a minute shifts the balance of the autonomic nervous system toward its calmer, parasympathetic side. A 2018 systematic review by Zaccaro and colleagues linked slow-breathing practice with higher heart-rate variability and with reports of more comfort and alertness and less anxiety.</p><p>Exhale length seems to matter. In a 2023 randomised study from Stanford, five minutes a day of exhale-focused breathing improved mood more than the same time spent on mindfulness meditation. These are small studies of healthy adults, so treat the pacer as a reset between tasks. It is not a treatment, and it does not replace medical care.</p>',
  sources=['Zaccaro, A., et al. (2018). How breath-control can change your life: a systematic review on psycho-physiological correlates of slow breathing. Frontiers in Human Neuroscience.','Balban, M. Y., et al. (2023). Brief structured respiration practices enhance mood and reduce physiological arousal. Cell Reports Medicine.']),
 dict(id='noise', slug='noise-mixer', name='Noise mixer', blurb='Brown, pink and white noise, rain and a low hum, mixed in your browser.',
  intro='Blend five steady sounds to mask a noisy room. The audio is generated on your device, so nothing downloads or streams, and your mix is remembered for next time.',
  how=['Press Play sound, then raise one slider at a time.','Start with brown noise around 40%. It is the least tiring for long sessions.','Add a little rain or pink noise if voices still cut through.','Keep the volume low enough that you could hold a conversation over it.'],
  why='<p>Steady broadband noise works mainly by masking: it raises the floor of the sound around you, so sudden noises such as speech, doors and notifications stand out less and pull your attention less often. White noise has equal energy at every frequency and sounds like hiss; pink and brown noise carry more low-frequency energy and sound softer and deeper.</p><p>The evidence that noise makes people think better is mixed. Mehta, Zhu and Cheema found that moderate ambient noise helped on creative tasks while loud noise hurt, and Söderlund’s group found that white noise helped inattentive children while slightly hurting attentive ones. The practical rule: use noise to cover distractions, keep it quiet, and turn it off if it starts to tire you.</p>',
  sources=['Mehta, R., Zhu, R., &amp; Cheema, A. (2012). Is noise always bad? Exploring the effects of ambient noise on creative cognition. Journal of Consumer Research.','Söderlund, G., Sikström, S., &amp; Smart, A. (2007). Listen to the noise: noise is beneficial for cognitive performance in ADHD. Journal of Child Psychology and Psychiatry.']),
 dict(id='matrix', slug='eisenhower-matrix', name='Eisenhower matrix', blurb='Sort tasks by urgent and important, then act on each box differently.',
  intro='Put every task in one of four boxes. The boxes tell you what to do with it: do it today, schedule it, hand it off or drop it. Your matrix is saved in this browser.',
  how=['Empty your head: add every task that is nagging you, without sorting yet.','Move each task to a box. Important means it serves your own goals; urgent means someone is waiting.','Do the “Do today” box first, then put a date on everything in “Schedule it”.','Be strict with the bottom row. Most overload lives there.'],
  why='<p>The grid is named after Dwight D. Eisenhower, who in a 1954 speech quoted a former college president: “I have two kinds of problems, the urgent and the important. The urgent are not important, and the important are never urgent.” Stephen Covey turned the idea into the four-box matrix in The 7 Habits of Highly Effective People.</p><p>It works because urgency distorts judgement. In a series of experiments published in 2018, Zhu, Yang and Hsee found that people chose urgent tasks with small payoffs over important tasks with larger ones, even when the urgency was an illusion. Writing tasks into boxes forces the comparison your attention would otherwise skip.</p>',
  sources=['Covey, S. R. (1989). The 7 Habits of Highly Effective People.','Zhu, M., Yang, Y., &amp; Hsee, C. K. (2018). The mere urgency effect. Journal of Consumer Research.']),
 dict(id='decide', slug='decision-matrix', name='Decision matrix', blurb='Score options against weighted criteria and see which one leads.',
  intro='List your options, list what matters, weight each criterion from 1 to 10, and score every option from 1 to 10. The table calculates a weighted score and tells you how solid the lead is.',
  how=['Name two to five real options. Include “do nothing” if it is one.','Add the criteria you would defend to a colleague, and weight them before you score anything.','Score one criterion at a time across all options, not one option at a time.','Change a weight you are unsure of. If the winner flips, you have found the real question.'],
  why='<p>Weighing options on paper is old advice. In a 1772 letter to Joseph Priestley, Benjamin Franklin described his “moral or prudential algebra”: list the reasons for and against, weight them, and strike out those that balance. A weighted decision matrix is the same idea with numbers, known in engineering as a Pugh matrix and in economics as multi-criteria analysis.</p><p>The value is less in the final score than in the steps. Setting weights first stops you from bending the criteria toward the option you already like, and scoring one criterion at a time makes the comparison fairer. Treat a narrow lead as a tie.</p>',
  sources=['Franklin, B. (1772). Letter to Joseph Priestley, 19 September 1772.','Pugh, S. (1991). Total Design: Integrated Methods for Successful Product Engineering.']),
 dict(id='blocks', slug='time-block-planner', name='Time-block planner', blurb='Paint your day in half-hour blocks of deep work, shallow work, meetings and breaks.',
  intro='Give every half hour of the working day a job. Choose a block type, add an optional label, and click slots to paint them. The planner totals each type and prints cleanly.',
  how=['Set the hours your day really runs, not the hours you wish it ran.','Paint meetings and fixed commitments first.','Place one or two deep-work blocks where your energy is highest, usually the morning.','Leave at least one empty block. Something will overrun.'],
  why='<p>Time blocking replaces the open-ended to-do list with a plan for where each hour goes. Cal Newport, who popularised the term “deep work”, argues that a blocked day gets noticeably more done than the same hours spent reacting, mostly because the decision about what to do next is made once, in advance.</p><p>Plan with the planning fallacy in mind. Kahneman and Tversky described it in 1979, and Buehler, Griffin and Ross later showed that people underestimate their own task times even when they know similar tasks overran before. Add a third to your first estimate and redraw the plan when the day changes; the plan is a tool, not a contract.</p>',
  sources=['Newport, C. (2016). Deep Work: Rules for Focused Success in a Distracted World.','Buehler, R., Griffin, D., &amp; Ross, M. (1994). Exploring the “planning fallacy”. Journal of Personality and Social Psychology.']),
]

